mapper.select:
SELECT COUNT(*) as totalCount, COUNT(CASE WHEN is_valid = 1 THEN 1 END) as validCount, COUNT(CASE WHEN quality_score >= 80 THEN 1 END) as highQualityCount, COALESCE(AVG(quality_score), 0) as avgQualityScore, COALESCE(MAX(quality_score), 0) as maxQualityScore, COALESCE(MIN(quality_score), 0) as minQualityScore FROM fund_plan_analysis WHERE is_deleted = 0
AND org_id = #{orgId}
AND plan_id = #{planId}
AND analysis_type = #{analysisType}

SELECT DATE_FORMAT(create_time, '%Y-%m') as month, COUNT(*) as analysisCount, COUNT(CASE WHEN is_valid = 1 THEN 1 END) as validCount, COALESCE(AVG(quality_score), 0) as avgQualityScore, COUNT(CASE WHEN quality_score >= 80 THEN 1 END) as highQualityCount FROM fund_plan_analysis WHERE org_id = #{orgId} AND is_deleted = 0
AND analysis_type = #{analysisType}
AND create_time >= DATE_SUB(CURDATE(), INTERVAL #{months} MONTH) GROUP BY DATE_FORMAT(create_time, '%Y-%m') ORDER BY month DESC

SELECT value_assessment, COUNT(*) as count, COALESCE(AVG(quality_score), 0) as avgQualityScore, COUNT(CASE WHEN is_valid = 1 THEN 1 END) as validCount, ROUND(COUNT(CASE WHEN is_valid = 1 THEN 1 END) * 100.0 / COUNT(*), 2) as validRate FROM fund_plan_analysis WHERE org_id = #{orgId} AND is_deleted = 0
AND create_time >= #{startDate}
AND create_time <= #{endDate}
GROUP BY value_assessment ORDER BY CASE value_assessment WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END

mapper.update:
UPDATE fund_plan_analysis SET is_valid = #{isValid}, valid_until = #{validUntil}, update_user = #{updateUser}, update_time = NOW() WHERE analysis_id IN
#{analysisId}
AND is_deleted = 0
